"import os

def write_file(path, content):
    """Helper to write file content, creating directories if needed."""
    dir_name = os.path.dirname(path)
    if dir_name:
        os.makedirs(dir_name, exist_ok=True)
    with open(path, 'w') as f:
        f.write(content)

